    proc = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    try:
        ps_proc = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.time()
    while True:
        try:
            if not ps_proc.is_running():
                break
            status = ps_proc.status()
            if status == psutil.STATUS_ZOMBIE:
                break
        except psutil.NoSuchProcess:
            break
        cpu_usage += ps_proc.cpu_percent(interval=0.1)
        mem_info = ps_proc.memory_info()
        if mem_info.rss > memory_usage:
            memory_usage = mem_info.rss
        if time.time() - start_time >= timeout:
            proc.terminate()
            break
    proc.terminate()
    proc.wait()
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}
